import postgres from "postgres";
const db=postgres(process.env.SUPABASE_DB_URL,{max:1,onnotice(){}});
const [u]=await db`select id from auth.users where raw_user_meta_data->>'qa_test'='delprobe' order by created_at desc limit 1`;
const [w]=await db`select id from public.workspaces where owner_id=${u.id}`;
const attempt=async(label,fn)=>{try{await db.begin(async tx=>{await fn(tx);console.log(label,'SUCCEEDS');throw new Error('ROLLBACK')})}catch(e){if(e.message!=='ROLLBACK')console.log(label,'FAILS',{code:e.code,msg:e.message,where:e.where?.slice(0,120)})}};
const tables=(await db`select table_name from information_schema.columns join information_schema.tables using(table_schema,table_name) where table_schema='public' and table_type='BASE TABLE' and column_name='workspace_id'`).map(r=>r.table_name);
const counts={};for(const t of tables){const[{n}]=await db.unsafe(`select count(*)::int n from public."${t}" where workspace_id=$1`,[w.id]);if(n)counts[t]=n}
console.log('fresh user rows',counts);
await attempt('delete categories+settings then workspace',async tx=>{for(const t of Object.keys(counts)) await tx.unsafe(`delete from public."${t}" where workspace_id=$1`,[w.id]);await tx`delete from public.workspaces where id=${w.id}`;});
await attempt('...then auth user',async tx=>{for(const t of Object.keys(counts)) await tx.unsafe(`delete from public."${t}" where workspace_id=$1`,[w.id]);await tx`delete from public.workspaces where id=${w.id}`;await tx`delete from auth.users where id=${u.id}`;});
console.log('non-QA users',(await db`select count(*)::int n from auth.users where not (email like '%example.invalid' or email like '%example.test')`)[0].n);
console.log('workspaces with financial rows, non-QA',await db`select count(*)::int workspaces, coalesce(sum((select count(*) from public.transactions t where t.workspace_id=w.id)),0)::int txns from public.workspaces w join auth.users u on u.id=w.owner_id where not (u.email like '%example.invalid' or u.email like '%example.test')`);
console.log('guard triggers',(await db`select tgrelid::regclass::text t,tgname from pg_trigger t join pg_proc p on p.oid=t.tgfoid where not tgisinternal and tgtype & 8 = 8 and tgrelid::regclass::text not like 'auth.%' and tgrelid::regclass::text not like 'storage.%' and tgrelid::regclass::text not like 'realtime.%' and tgrelid::regclass::text not like 'cron.%' and tgrelid::regclass::text not like 'vault.%' limit 15`).map(r=>r.t+':'+r.tgname));
await db.end({timeout:2});
EOF
