1	-- Settings "Reset all data": wipe the caller's workspace and recreate it exactly as signup does.
2	-- The replacement workspace gets a new id, so in-flight workflows holding the old id fail their
3	-- workspace foreign keys instead of writing old data back. Children are deleted before parents.
4	create function public.reset_workspace() returns void language plpgsql security definer set search_path='' as $$
5	declare ws uuid; owner uuid := auth.uid();
6	begin
7	  if owner is null then raise exception 'Unauthorized' using errcode='42501'; end if;
8	  select id into ws from public.workspaces where owner_id=owner for update;
9	  if not found then raise exception 'Workspace unavailable' using errcode='P0002'; end if;
10	  -- Deleted history is not undoable, so skip planning audit rows and link-edit guards.
11	  perform set_config('moneo.planning_undo','true',true);
12	  perform set_config('moneo.link_edit','on',true);
13	
14	  -- AI conversations, reviews.
15	  delete from public.saved_analyses where workspace_id=ws;
16	  delete from public.summary_runs where workspace_id=ws;
17	  delete from public.background_jobs where workspace_id=ws;
18	  delete from public.chat_requests where workspace_id=ws;
19	  delete from public.messages where workspace_id=ws;
20	  delete from public.conversations where workspace_id=ws;
21	  delete from public.dashboard_layouts where workspace_id=ws;
