33	  const resuming = running && !pending;
34	  usePolling(() => void fetch(`/api/conversations/${conversationId}`, { cache: "no-store" }).then(response => response.ok ? response.json() as Promise<Loaded> : null).then(data => {
35	    if (!data || data.running) return;
