44	    setPending(live.current);
45	    // A page or card just saved: show it without waiting for the whole answer.
46	    if (event.type === "tool" && event.state === "done" && ["write_page", "card_preset", "write_card", "remove_card"].includes(event.name ?? "")) router.refresh();
47	  }
