    const widget = (name: string) => page.locator(`[data-widget="${name}"]`);
    await expect(widget("goals")).toBeVisible();
    const box = async (name: string) => (await widget(name).boundingBox())!;

    // Dense packing: Goals fills the two free columns beside the first wide widget.
    expect(Math.abs((await box("goals")).y - (await box("history")).y)).toBeLessThan(2);

    const recent = await box("recent"), grid = (await page.locator("[data-widget]").first().locator("..").boundingBox())!;
    await widget("goals").hover();
    const grip = page.getByRole("button", { name: /^Move Goals/ });
    await drag(page, grip, { x: grid.x + grid.width - 40, y: recent.y + recent.height / 2 });
    await expect.poll(async () => Math.abs((await box("goals")).y - (await box("recent")).y)).toBeLessThan(2);
    expect((await box("goals")).x).toBeGreaterThan((await box("recent")).x);

    await expect.poll(async () => (await db`select items from public.dashboard_layouts where workspace_id=${workspace}`)[0].items).toEqual(["history", "recent", "goals"]);
    await page.reload();
    await expect(widget("goals")).toBeVisible();
    expect(Math.abs((await box("goals")).y - (await box("recent")).y)).toBeLessThan(2);

    // Below the last widget still counts as a place to drop.
    await widget("history").hover();
    const last = await box("goals");
    await drag(page, page.getByRole("button", { name: /^Move History/ }), { x: last.x + 20, y: last.y + last.height + 200 });
    await expect.poll(async () => (await db`select items from public.dashboard_layouts where workspace_id=${workspace}`)[0].items).toEqual(["recent", "goals", "history"]);
  } finally {
    await deleteDisposableUser(db, user);
    await db.end();
  }
});
